"""Self-contained XGBoost solution. Change this file; use evaluate.py to test.

Final simplified model (identical to trial H19; the switchable research version is kept in
scratch/train_research_version.py):
  * features: log10 proposed penalty, log10 penalty per cited regulation, log10 penalty per violation
    category (all monotone increasing), and five region indicators;
  * training rows weighted by ((i+1)/n)**4 over their order in the supplied frame (the release's training
    file is chronological; no date column is used and scoring rows carry no order information);
  * bagging-style smoothing: each of 600 shallow trees sees half the rows and half the columns per split.
"""
import numpy as np
import pandas as pd
import xgboost as xgb

RECENCY_POWER = 4.0
REGIONS = ["Central", "Eastern", "Southern", "Southwest", "Western"]
MONOTONE = {"log_penalty": 1, "log_penalty_per_reg": 1, "log_penalty_per_cat": 1}
PARAMS = {
    "n_estimators": 600,
    "max_depth": 2,
    "learning_rate": 0.0075,
    "subsample": 0.5,
    "colsample_bynode": 0.5,
    "min_child_weight": 5,
    "reg_lambda": 5.0,
    "gamma": 0.0,
}


def _num(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return np.nan


def _row_features(row, med):
    p = _num(row.get("proposed_penalty_usd"))
    lp = np.log10(p) if p == p and p > 0 else np.nan
    f = {"log_penalty": lp}
    # A missing or zero item count is replaced by the training median so the ratio stays defined.
    for name, col in (("log_penalty_per_reg", "cited_regulation_count"), ("log_penalty_per_cat", "violation_category_count")):
        c = _num(row.get(col))
        if not (c == c and c > 0):
            c = med[col]
        f[name] = lp - np.log10(c) if c == c and c > 0 else np.nan
    region = row.get("region")
    for r in REGIONS:
        f["region_" + r] = float(region == r)
    return f


def _matrix(X, med, cols=None):
    recs = [_row_features(r, med) for r in X.to_dict("records")]
    return pd.DataFrame.from_records(recs, columns=cols).astype(np.float32)


def fit(X_train, y_train, *, seed, threads):
    n = len(X_train)
    med = {
        c: float(np.nanmedian(pd.to_numeric(X_train[c], errors="coerce")))
        for c in ("cited_regulation_count", "violation_category_count")
    }
    Z = _matrix(X_train, med)
    cols = list(Z.columns)
    w = ((np.arange(n) + 1.0) / n) ** RECENCY_POWER
    w = w / w.mean()
    m = xgb.XGBClassifier(
        tree_method="hist", random_state=seed, n_jobs=threads, monotone_constraints=dict(MONOTONE), **PARAMS
    )
    m.fit(Z, np.asarray(y_train), sample_weight=w)
    return {"cols": cols, "med": med, "model": m}


def prepare(state, X):
    return _matrix(X, state["med"], state["cols"])


def predict(model, X):
    return model["model"].predict_proba(prepare(model, X))[:, 1]
