"""Training-only: component value of the final model on the evaluator's backtest split (fit rows before
2012-10-24, score the 167 later training rows), with uncertainty from resampling the FIT rows (30 bootstraps,
order preserved) and paired differences against the final model. Never reads eval.csv."""
import importlib.util, json, numpy as np, pandas as pd, xgboost as xgb
from sklearn.metrics import roc_auc_score as auc
F=json.load(open('release/reproduction/construction.json'))['quality']['features']
tr=pd.read_csv('release/extract/public/train.csv'); cut=(pd.to_datetime(tr.notice_date)<pd.Timestamp('2012-10-24')).to_numpy()
A=tr[cut].reset_index(drop=True); B=tr[~cut].reset_index(drop=True); ya=A.penalty_reduced.to_numpy(); yb=B.penalty_reduced.to_numpy(); n=len(A)
REG=["Central","Eastern","Southern","Southwest","Western"]
