def mat(d,region=True):
    Z=pd.DataFrame({'log_penalty':np.log10(d.proposed_penalty_usd.to_numpy(float))})
    if region:
        for r in REG: Z['region_'+r]=(d.region.to_numpy()==r).astype(float)
    return Z.astype(np.float32)
def run(idx,w0=0.2,mono=True,region=True,params=P):
    d=A.iloc[idx]; pen=d.proposed_penalty_usd.to_numpy(float); w=np.where(pen%1000==0,w0,1.0); w=w/w.mean()
    kw=dict(monotone_constraints={'log_penalty':1}) if mono else {}
